#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# FacilityFlow — VPS EU staging/pilota (docs/ops/NEXT_VPS.md).
# Scrive valori in .env.prod locale (template); sul VPS copia in /etc/facilityflow/.env.prod.
ENV_FILE="${ENV_FILE:-.env.prod}"
TOTAL_STAGES=8

banner "FacilityFlow — VPS EU (staging / pilota)"

stage "Preflight locale"
say "Verifica artefatti repo + compose.prod (niente host remoto)."
step "Dalla root del repo: npm run vps:preflight"
pause "Preflight OK? Enter per continuare"
if [[ ! -f .env.prod.example ]]; then
  warn "manca .env.prod.example — interrompi e ripristina il repo"
  exit 1
fi
if [[ ! -f "$ENV_FILE" ]]; then
  cp .env.prod.example "$ENV_FILE"
  note "creato $ENV_FILE da .env.prod.example"
fi
chmod 600 "$ENV_FILE" 2>/dev/null || true

stage "Provisiona VPS EU"
say "Crea un VPS in regione EU (≥ 2 vCPU / 4 GB RAM, disco ≥ 40 GB)."
step "Provider a scelta (Hetzner / OVH / Scaleway / …) — Ubuntu 22.04+ LTS"
step "Abilita accesso SSH con chiave; annota l'IP pubblico"
ask VPS_IP "IP pubblico del VPS:"
ask VPS_SSH_USER "Utente SSH (es. root o ubuntu):"
write_env VPS_IP "$VPS_IP"
write_env VPS_SSH_USER "$VPS_SSH_USER"
note "Connessione tipica: ssh ${VPS_SSH_USER}@${VPS_IP}"

stage "DNS"
say "Punta il dominio applicativo all'IP del VPS (A/AAAA)."
ask FF_DOMAIN "Dominio (es. staging.example.com o app.example.com):"
write_env FF_DOMAIN "$FF_DOMAIN"
write_env NEXT_PUBLIC_APP_URL "https://${FF_DOMAIN}"
step "Crea record A ${FF_DOMAIN} → ${VPS_IP} (TTL basso finché non propaga)"
pause "DNS creato? Enter quando dig ${FF_DOMAIN} risolve l'IP"

stage "Firewall UFW sul VPS"
say "Sul VPS (via SSH) apri solo 22/80/443 — vedi docs/ops/FIREWALL.md"
step "ssh ${VPS_SSH_USER}@${VPS_IP}"
step "sudo ufw default deny incoming && sudo ufw default allow outgoing"
step "sudo ufw allow OpenSSH && sudo ufw allow 80/tcp && sudo ufw allow 443/tcp"
step "sudo ufw enable && sudo ufw status verbose"
warn "Non pubblicare 5432 / 8333 / 3000 su 0.0.0.0"
pause "UFW configurato? Enter"

stage "Secret .env.prod"
say "Genera secret forti e scrivili in ${ENV_FILE} (poi copia sul VPS mode 600)."
ask_secret POSTGRES_PASSWORD "POSTGRES_PASSWORD (es. openssl rand -hex 24):"
ask_secret AUTH_SECRET "AUTH_SECRET (es. openssl rand -base64 32):"
ask_secret S3_ACCESS_KEY "S3_ACCESS_KEY:"
ask_secret S3_SECRET_KEY "S3_SECRET_KEY:"
ask SMTP_HOST "SMTP_HOST (relay reale, no Mailpit):"
ask SMTP_PORT "SMTP_PORT (es. 587):"
ask SMTP_FROM "SMTP_FROM (es. FacilityFlow <noreply@domain>):"
write_env POSTGRES_USER "facilityflow"
write_env POSTGRES_DB "facilityflow"
write_env POSTGRES_PASSWORD "$POSTGRES_PASSWORD"
write_env AUTH_SECRET "$AUTH_SECRET"
write_env S3_ACCESS_KEY "$S3_ACCESS_KEY"
write_env S3_SECRET_KEY "$S3_SECRET_KEY"
write_env S3_BUCKET "facilityflow-attachments"
write_env SMTP_HOST "$SMTP_HOST"
write_env SMTP_PORT "$SMTP_PORT"
write_env SMTP_FROM "$SMTP_FROM"
warn "Non committare ${ENV_FILE}. Sul VPS: /etc/facilityflow/.env.prod chmod 600"

stage "Clone + Compose sul VPS"
say "Installa Docker Engine + Compose plugin, poi avvia lo stack prod."
step "git clone <repo> /opt/facilityflow && cd /opt/facilityflow && git checkout v0.1.0  # o develop"
step "sudo mkdir -p /etc/facilityflow && sudo cp ${ENV_FILE} /etc/facilityflow/.env.prod && sudo chmod 600 …"
step "docker compose -f compose.prod.yaml --env-file /etc/facilityflow/.env.prod up -d --build"
step "docs: docs/ops/COMPOSE_PROD.md"
pause "Stack up? Enter"

stage "Migrate + seed staging + health"
say "Solo staging: migrate + seed pilota. Prod: migrate senza seed QA."
step "bash scripts/deploy-migrate.sh  (o docs/ops/MIGRATE.md — container app)"
step "Staging only: npm run db:seed:pilot dentro il container app"
step "curl -sf https://${FF_DOMAIN}/api/health/live && curl -sf https://${FF_DOMAIN}/api/health/ready"
pause "Health HTTPS OK? Enter"

stage "Exit S5 — smoke e gap list"
say "Chiudi i gap rimanenti in docs/product/sprints/S5-EXIT-GAPS.md"
step "Smoke UI Flusso A: docs/ops/SMOKE_FLUSSO_A.md"
step "scripts/verify-security-headers.sh https://${FF_DOMAIN}/"
step "Restore drill remoto: docs/ops/BACKUP.md + runbooks/RESTORE.md"
step "Aggiorna S5-EXIT-GAPS.md → GO staging / GO pilota"
step "Checklist: docs/ops/RELEASE_CHECKLIST.md"
pause "Annotato? Enter per chiudere il wizard"

finish
note "Prossimi comandi utili: npm run vps:preflight · docs/ops/NEXT_VPS.md"
